def chunked_even(iterable, n):
    """Break *iterable* into lists of approximately length *n*.
    Items are distributed such the lengths of the lists differ by at most
    1 item.

    >>> iterable = [1, 2, 3, 4, 5, 6, 7]
    >>> n = 3
    >>> list(chunked_even(iterable, n))  # List lengths: 3, 2, 2
    [[1, 2, 3], [4, 5], [6, 7]]
    >>> list(chunked(iterable, n))  # List lengths: 3, 3, 1
    [[1, 2, 3], [4, 5, 6], [7]]

    """
    def batch_iterator(it, n):
        batch = []
        for item in it:
            batch.append(item)
            if len(batch) == n:
                yield batch
                batch = []
        if batch:
            yield batch

    def distribute_batches(batches, n):
        total_length = sum(len(batch) for batch in batches)
        batch_size = total_length // n
        extra = total_length % n

        for i, batch in enumerate(batches):
            if i < extra:
                yield batch[:batch_size + 1]
            else:
                yield batch[:batch_size]

    batches = list(batch_iterator(iterable, n))
    return distribute_batches(batches, n)

